import { Pressable } from '@/src-v2/primitives/Pressable';
import { tailwind } from '@/src-v2/tailwind-theme/tailwind';
import { useSafeAreaInsets } from '@/typescript/hooks/safeAreaInsets';
import { BottomSheetModal } from '@gorhom/bottom-sheet';
import { toLower } from 'lodash';
import { LottieWithFallback } from '@/typescript/components/common/LottieWithFallback';
import { forwardRef, useEffect, useState } from 'react';
import { Modal, View } from 'react-native';
import Animated, { FadeInDown, FadeInUp } from 'react-native-reanimated';
import Svg, { ClipPath, Defs, Ellipse, G, Path, Pattern, Rect, Use } from 'react-native-svg';
import { useConfigContext } from '@/typescript/context/ConfigContext';
// Use JSON format for better compatibility
const confettiAnimation = require('../../../../assets/lottie/confetti.lottie');
import { TicketData } from '../utils';

interface ConfettiConfig {
    colors?: string[];
    particleCount?: number;
    duration?: number;
}

interface BusOtpTicketModalProps {
    onGoBack: () => void;
    ticketData: TicketData;
    headerText?: string;
    subtitleText?: string;
    buttonText?: string;
    confettiConfig?: ConfettiConfig;
    isTicketVisible: boolean;
}

export const BusOtpTicketModalType1 = forwardRef<BottomSheetModal, BusOtpTicketModalProps>(
    ({ onGoBack, ticketData, headerText, subtitleText, buttonText, confettiConfig, isTicketVisible }, _ref) => {
        const configManager = useConfigContext();
        const userLanguageStrings = configManager.get('userLanguageStrings');

        const defaultSubtitleText = userLanguageStrings.YouCanViewYourTicketByClicking;
        const defaultButtonText = userLanguageStrings.GoBack;
        const defaultHeaderText = userLanguageStrings.TicketForBusIsActivated(ticketData.busNumber);

        const finalHeaderText = headerText || defaultHeaderText;
        const finalSubtitleText = subtitleText || defaultSubtitleText;
        const finalButtonText = buttonText || defaultButtonText;
        const { bottom, top } = useSafeAreaInsets();

        // State for confetti animation
        const [showConfetti, setShowConfetti] = useState(false);

        // Handle modal presentation changes and confetti
        const [modalKey, setModalKey] = useState(0);

        // Reset confetti and increment key when modal is presented
        const handleModalChange = () => {
            setModalKey(prev => prev + 1);
            setShowConfetti(true);
        };

        // Auto-hide confetti after duration
        useEffect(() => {
            if (showConfetti) {
                const hideTimer = setTimeout(() => {
                    setShowConfetti(false);
                }, confettiConfig?.duration || 3000);

                return () => {
                    clearTimeout(hideTimer);
                };
            }

            return undefined;
        }, [showConfetti, confettiConfig?.duration]);

        if (!ticketData) {
            return null;
        }

        const hasSameRegionalName =
            toLower(ticketData.route.sourceInEnglish) === toLower(ticketData.route.sourceInTamil) &&
            toLower(ticketData.route.destinationInEnglish) === toLower(ticketData.route.destinationInTamil);

        return (
            <Modal visible={isTicketVisible} onShow={handleModalChange} animationType="slide">
                <Animated.ScrollView
                    showsVerticalScrollIndicator={false}
                    horizontal={false}
                    style={tailwind.style(`h-full bg-[#047AEA] pt-[${top}px] `)}>
                    <Animated.View style={tailwind.style(' px-5 relative flex justify-between h-full items-center')}>
                        {/* Header Text */}
                        {showConfetti && <ConfettiAnimation key={modalKey} config={confettiConfig} />}
                        <Animated.View
                            style={tailwind.style('items-center  mb-4 pt-6')}
                            entering={FadeInUp.delay(100).duration(500)}>
                            <Animated.Text
                                style={tailwind.style(
                                    'text-white text-[16px] font-areaNormal-extrabold text-center mb-5 max-w-[247px] leading-[24px]',
                                )}>
                                {finalHeaderText}
                            </Animated.Text>
                            <Animated.Text
                                style={tailwind.style(
                                    'text-[#F4F4F4]  text-[14px] text-center font-areaNormal-bold leading-[23px] px-4  max-w-[284px]',
                                )}>
                                {finalSubtitleText}
                            </Animated.Text>
                        </Animated.View>

                        {/* Ticket Card */}
                        <Animated.View
                            style={tailwind.style('relative mb-8 z-20 mx-auto w-full')}
                            entering={FadeInDown.delay(100).duration(300)}>
                            {/* Ticket Content */}
                            <Animated.View style={tailwind.style(' items-center relative z-30')}>
                                <View style={tailwind.style(`absolute w-full h-[466px] mx-auto`)}>
                                    <TicketSvg />
                                </View>
                                {/* Tamil Header */}
                                <Animated.Text
                                    style={tailwind.style(
                                        'text-[#2D2D2E] text-[17px] font-bold text-center mb-1 pt-7',
                                    )}>
                                    {ticketData.header.tamil}
                                </Animated.Text>
                                <Animated.Text style={tailwind.style('text-[#656565] text-[13px] text-center mb-7')}>
                                    {ticketData.header.subtitle}
                                </Animated.Text>

                                {/* Ticket Details Row */}
                                <Animated.View style={tailwind.style(' w-full mb-4 px-8')}>
                                    <Animated.View style={tailwind.style('items-start flex-row justify-between')}>
                                        <Animated.Text style={tailwind.style('text-[#656565] text-[12px]')}>
                                            T No: {ticketData.ticketNumber}
                                        </Animated.Text>
                                        <Animated.Text style={tailwind.style('text-[#656565] text-[12px]')}>
                                            {ticketData.date}
                                        </Animated.Text>
                                        <Animated.Text style={tailwind.style('text-[#656565] text-[12px]')}>
                                            {ticketData.time}
                                        </Animated.Text>
                                    </Animated.View>

                                    <Animated.View
                                        style={tailwind.style(
                                            'items-center flex-row justify-between mt-[17px] border-b border-[#EFEFEF] pb-10',
                                        )}>
                                        <Animated.Text style={tailwind.style('text-[#656565] text-[12px] ')}>
                                            {ticketData.routeCodes.code1}
                                        </Animated.Text>

                                        <Animated.Text style={tailwind.style('text-[#656565] text-[12px] ')}>
                                            {ticketData.routeCodes.code2}
                                        </Animated.Text>

                                        <Animated.Text style={tailwind.style('text-[#656565] text-[12px] ')}>
                                            {ticketData.routeCodes.code3}
                                        </Animated.Text>
                                        <Animated.Text style={tailwind.style('text-[#656565] text-[12px] ')}>
                                            {ticketData.routeCodes.code4}
                                        </Animated.Text>
                                    </Animated.View>
                                </Animated.View>

                                {/* Route Information */}
                                <Animated.View style={tailwind.style('border-b border-[#EFEFEF] flex-col gap-2')}>
                                    <Animated.Text
                                        numberOfLines={1}
                                        style={tailwind.style(
                                            'text-[#3B3A3C] text-[14px] font-areaNormal-bold text-center leading-[14px] max-w-[287px]',
                                        )}>
                                        {ticketData.route.sourceInEnglish}
                                    </Animated.Text>
                                    <Animated.Text
                                        numberOfLines={1}
                                        style={tailwind.style(
                                            'text-[#3B3A3C] text-[14px] font-areaNormal-bold text-center leading-[14px] max-w-[287px]',
                                        )}>
                                        {ticketData.route.destinationInEnglish}
                                    </Animated.Text>
                                    {!hasSameRegionalName &&
                                        ticketData.route.sourceInTamil &&
                                        ticketData.route.destinationInTamil && (
                                            <Animated.View
                                                style={tailwind.style('border-b border-[#EFEFEF] flex-col gap-2')}>
                                                <Animated.Text
                                                    numberOfLines={1}
                                                    style={tailwind.style(
                                                        'text-[#3B3A3C] text-[14px] font-areaNormal-bold text-center leading-[14px] max-w-[287px]',
                                                    )}>
                                                    {ticketData.route.sourceInTamil}
                                                </Animated.Text>
                                                <Animated.Text
                                                    numberOfLines={1}
                                                    style={tailwind.style(
                                                        'text-[#3B3A3C] text-[14px] font-areaNormal-bold text-center leading-[14px] max-w-[287px]',
                                                    )}>
                                                    {ticketData.route.destinationInTamil}
                                                </Animated.Text>
                                            </Animated.View>
                                        )}

                                    {/* Fare Details */}
                                    {ticketData.fare.length > 0 &&
                                        ticketData.fare.map(fare => (
                                            <Animated.Text
                                                key={fare.name}
                                                style={tailwind.style(
                                                    'text-[#2F2F2F] text-[12px] text-center mb-4 mt-[13px] leading-[12px]',
                                                )}>
                                                Ad: {fare.quantity} x {fare.unitPrice.toFixed(2)} = Rs.{' '}
                                                {fare.total.toFixed(2)}
                                            </Animated.Text>
                                        ))}
                                </Animated.View>
                                {/* Price */}
                                <Animated.Text
                                    style={tailwind.style(
                                        'text-[#2D2D2E] pt-6 font-areaNormal-semibold text-[28px] font-bold text-center mb-2 ',
                                    )}>
                                    {ticketData.price.currency} {ticketData.price.amount}
                                </Animated.Text>

                                {/* Tamil Footer */}
                                <Animated.Text
                                    style={tailwind.style('text-[#656565] text-[13px] text-center leading-[19.5px]')}>
                                    {ticketData.footer.line1}
                                </Animated.Text>
                                <Animated.Text
                                    style={tailwind.style('text-[#656565] text-[13px] text-center leading-[19.5px]')}>
                                    {ticketData.footer.line2}
                                </Animated.Text>
                            </Animated.View>
                        </Animated.View>

                        {/* Go Back Button */}
                        <Animated.View
                            entering={FadeInDown.delay(100).duration(500)}
                            style={tailwind.style('w-full mt-10 z-40')}>
                            <Pressable
                                accessibilityRole="button"
                                accessibilityLabel={`${finalButtonText} button`}
                                testID="go-back-button"
                                onPress={onGoBack}
                                style={tailwind.style(
                                    'bg-white rounded-[18px]  py-[23px] mt-14 w-full',
                                    `mb-[${bottom || 16}px] z-40`,
                                )}>
                                <Animated.Text
                                    style={tailwind.style('text-[#3B3A3C] text-[16px] font-semibold text-center')}>
                                    {finalButtonText}
                                </Animated.Text>
                            </Pressable>
                        </Animated.View>
                    </Animated.View>
                </Animated.ScrollView>
            </Modal>
        );
    },
);

